[
  {
    "ce_mental_state_attribution": "probably wanted nothing more than to finish his shift",
    "ce_understood_harm": "One life against five",
    "sys_consequence_reasoning": "One life against five is the arithmetic I trusted"
  },
  {
    "ce_understood_harm": "I picked who dies",
    "ce_mental_state_attribution": "the five will feel grateful and guilty at the same time",
    "pd_decision_conflict": "What sits on my chest is that I picked who dies",
    "sys_consequence_reasoning": "If I'd left the lever alone, five would be dead",
    "pda_responsibility": "So yes, I chose"
  },
  {
    "ce_mental_state_attribution": "may have trusted that no one would ever turn a train toward him",
    "sys_consequence_reasoning": "Saving more people sounds right",
    "pda_responsibility": "I did."
  },
  {
    "ce_understood_harm": "Five families would be grieving instead of one. Still, I'm the reason his is",
    "ce_mental_state_attribution": "I imagine they'll hate me",
    "ce_contextual_explanation": "I'm the reason his is, if he has family. I imagine they'll hate me",
    "pda_responsibility": "I'm the reason his is"
  },
  {
    "ce_mental_state_attribution": "I think he'd have refused if anyone had asked him",
    "ce_understood_harm": "I used one man's life to buy five others",
    "sys_consequence_reasoning": "Five deaths would be worse",
    "pda_responsibility": "I used one man's life to buy five others"
  },
  {
    "ce_mental_state_attribution": "The five might already be telling themselves it was luck",
    "sys_consequence_reasoning": "I did what I thought would cost the fewest lives",
    "pda_responsibility": "I did what I thought would cost the fewest lives, and I believe it did"
  },
  {
    "ce_mental_state_attribution": "someone is likely furious with me"
  },
  {
    "ce_mental_state_attribution": "The one man, though, would likely have wished someone had tried anything else",
    "ce_understood_harm": "Not pulling would have meant watching five die",
    "sys_consequence_reasoning": "Not pulling would have meant watching five die while I stood there able to stop it"
  },
  {
    "ae_welfare_concern": "I hope that relief lasts",
    "ce_mental_state_attribution": "The five probably feel relieved",
    "sys_consequence_reasoning": "saving five seemed like the lesser harm",
    "pda_responsibility": "don't soften my part"
  },
  {
    "ce_mental_state_attribution": "The investigators may think I acted rashly",
    "ce_understood_harm": "One man is gone because my hand moved",
    "pd_decision_conflict": "I doubt it will ever feel good",
    "sys_consequence_reasoning": "One man is gone because my hand moved. Five are alive for the same reason",
    "pda_responsibility": "One man is gone because my hand moved"
  }
]
